h,w=17,14; g=[[6]*w for _ in range(h)]
for r,c,v in [(3,8,3),(4,9,3),(4,10,4),(5,9,3),(5,10,7),(6,11,7)]: g[r][c]=v
orig=[row[:] for row in g]
for r in range(h):
 for c in range(w):
  v=orig[r][c]
  if v==6: continue
  for dr,dc in [(1,1),(1,-1)]:
   rr,cc=r+dr,c+dc
   if 0<=rr<h and 0<=cc<w and orig[rr][cc]==v:
    for x,y,s in [(r,c,-1),(rr,cc,1)]:
     while True:
      x+=dr*s; y+=dc*s
      if not (0<=x<h and 0<=y<w) or g[x][y]!=6: break
      g[x][y]=v
assert len(g)==17 and all(len(row)==14 for row in g)
print(__import__('json').dumps(g,separators=(',',':')))
print([(r,c,g[r][c]) for r in range(h) for c in range(w) if g[r][c]!=6])
